SELECT g, y, ROUND(SUM(dr),2) dr, ROUND(SUM(cr),2) cr FROM (SELECT CASE WHEN t.ACCOUNT_NO LIKE '1110%' OR t.ACCOUNT_NO LIKE '1120%' THEN 'FAC' WHEN t.ACCOUNT_NO LIKE '1111%' OR t.ACCOUNT_NO LIKE '1121%' THEN 'ACD' WHEN t.ACCOUNT_NO LIKE '113%' THEN 'WIP' WHEN t.ACCOUNT_NO LIKE '2112%' OR t.ACCOUNT_NO LIKE '2113%' OR t.ACCOUNT_NO LIKE '2125%' THEN 'LOAN' WHEN t.ACCOUNT_NO LIKE '1262%' THEN 'DINT' WHEN t.ACCOUNT_NO LIKE '2128%' THEN 'DIV' WHEN t.ACCOUNT_NO = '2111001' THEN 'EOSB' WHEN t.ACCOUNT_NO = '2111003' THEN 'VAC' WHEN t.ACCOUNT_NO = '1240008' THEN 'PROV' WHEN t.ACCOUNT_NO = '2123003' THEN 'ZAK' ELSE NULL END g, EXTRACT(YEAR FROM t.VM_DATE) y, t.DR_AMOUNT dr, t.CR_AMOUNT cr FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND t.VOUCHER_NO<>'JV1-24/04043' AND NOT EXISTS (SELECT 'X' FROM {P}FINANCIAL_YEARS f WHERE f.GL_VOUCHER_NO=t.VOUCHER_NO)) WHERE g IS NOT NULL GROUP BY g, y ORDER BY g, y
